type Direction = "up" | "down" | "left" | "right";

function move(x: number, y: number, dir: Direction): [number, number] {
  switch (dir) {
    case "up": return [x, y - 1];
    case "down": return [x, y + 1];
    case "left": return [x - 1, y];
    case "right": return [x + 1, y];
  }
}

